142	static int audio_graph_config_pointers(AVFilterGraph* graph)
143	{
144	    FFFilterGraph* ffgraph = fffiltergraph(graph);
145	    int sink_links_count = 0, n = 0;
146	    FilterLinkInternal** sinks;
147	    FilterLinkInternal* li;
148	    AVFilterContext* f;
149	    unsigned i, j;
150	
151	    for (i = 0; i < graph->nb_filters; i++) {
152	        f = graph->filters[i];
153	        for (j = 0; j < f->nb_inputs; j++) {
154	            li = (FilterLinkInternal*)f->inputs[j];
155	            li->age_index = -1;
156	        }
157	        for (j = 0; j < f->nb_outputs; j++) {
158	            li = (FilterLinkInternal*)f->outputs[j];
159	            li->age_index = -1;
160	        }
161	        if (!f->nb_outputs) {
162	            if (f->nb_inputs > INT_MAX - sink_links_count)
163	                return AVERROR(EINVAL);
164	            sink_links_count += f->nb_inputs;
165	        }
166	    }
167	    sinks = av_calloc(sink_links_count, sizeof(*sinks));
168	    if (!sinks)
169	        return AVERROR(ENOMEM);
170	    for (i = 0; i < graph->nb_filters; i++) {
171	        f = graph->filters[i];
172	        if (!f->nb_outputs) {
173	            for (j = 0; j < f->nb_inputs; j++) {
174	                li = (FilterLinkInternal*)f->inputs[j];
175	                sinks[n] = li;
176	                sinks[n]->age_index = n;
177	                n++;
178	            }
179	        }
180	    }
181	
182	    ffgraph->sink_links = sinks;
183	    ffgraph->sink_links_count = sink_links_count;
184	    return 0;
185	}
