217	static int audio_graph_load(MediaGraphPriv* priv, char* conf)
218	{
219	    char graph_desc[MAX_GRAPH_SIZE];
220	    AVFilterInOut* input = NULL;
221	    AVFilterInOut* output = NULL;
222	    char* subgraph_start;
223	    int ret;
224	    int fd;
225	
226	    av_log_set_callback(audio_graph_log_callback);
227	#ifdef CONFIG_MEDIA_TRACE
228	    av_trace_set_callback(media_trace_begin, media_trace_end);
229	#endif
230	    avdevice_register_all();
231	
232	    MEDIA_INFO("%s, loadgraph from file: %s\n", __func__, conf);
233	
234	    fd = open(conf, O_RDONLY | O_BINARY | O_CLOEXEC);
235	    if (fd < 0) {
236	        MEDIA_ERR("%s, can't open media graph file\n", __func__);
237	        return -errno;
238	    }
239	
240	    ret = read(fd, graph_desc, MAX_GRAPH_SIZE);
241	    close(fd);
242	    if (ret < 0)
243	        return -errno;
244	    else if (ret == MAX_GRAPH_SIZE)
245	        return -EFBIG;
246	
247	    graph_desc[ret] = 0;
248	
249	    MEDIA_INFO("%s, graph_desc:\n%s\n", __func__, graph_desc);
250	    subgraph_start = strstr(graph_desc, SUBGRAPH_PARSER_FLAGS);
251	    if (subgraph_start)
252	        *subgraph_start = '\0';
253	
254	    priv->graph = avfilter_graph_alloc();
255	    if (!priv->graph)
256	        return -ENOMEM;
257	
258	    ret = avfilter_graph_parse2(priv->graph, graph_desc, &input, &output);
259	    if (ret < 0) {
260	        MEDIA_ERR("%s, media graph parse error\n", __func__);
261	        goto out;
262	    }
263	
264	    avfilter_inout_free(&input);
265	    avfilter_inout_free(&output);
266	
267	    avfilter_graph_set_auto_convert(priv->graph, AVFILTER_AUTO_CONVERT_NONE);
268	
269	    ret = audio_graph_config_pointers(priv->graph);
270	    if (ret < 0)
271	        goto out;
272	
273	    /* set the status of all links to AVERROR_EOF */
274	    audio_graph_set_links_status(priv->graph, AVERROR_EOF);
275	
276	    priv->graph->opaque = priv;
277	
278	    if (subgraph_start) {
279	        char* current = subgraph_start + strlen(SUBGRAPH_PARSER_FLAGS);
280	        while (current) {
281	            char *colon, *config_end, *subgraph_name;
282	            int found_subgraph = 0;
283	            char filter_name[64];
284	
285	            // Skip whitespace
286	            while (*current == ' ' || *current == '\n' || *current == '\r')
287	                current++;
288	
289	            colon = strchr(current, ':');
290	            if (!colon) {
291	                MEDIA_ERR("Error in parsing subgraph filter name.\n");
292	                ret = -EINVAL;
293	                goto out;
294	            }
295	
296	            *colon = '\0';
297	            subgraph_name = current;
298	            current = colon + 1;
299	
300	            config_end = strstr(current, SUBGRAPH_PARSER_FLAGS);
301	            if (config_end)
302	                *config_end = '\0';
303	
304	            MEDIA_INFO("Found subgraph %s with config: %s\n", subgraph_name, current);
305	
306	            snprintf(filter_name, sizeof(filter_name), "asubgraph@%s", subgraph_name);
307	            for (int i = 0; i < priv->graph->nb_filters; i++) {
308	                AVFilterContext* filter = priv->graph->filters[i];
309	                if (filter->name && !strcmp(filter->name, filter_name)) {
310	                    ret = avfilter_process_command(filter, "graph_parse", current, NULL, 0, 0);
311	                    if (ret < 0) {
312	                        MEDIA_ERR("Failed to parse subgraph config for %s:%s, %s\n",
313	                            filter_name, current, av_err2str(ret));
314	                        goto out;
315	                    }
316	
317	                    found_subgraph = 1;
318	                    MEDIA_INFO("Successfully parsed subgraph config for %s:%s\n",
319	                        filter_name, current);
320	                    break;
321	                }
322	            }
323	
324	            if (!found_subgraph) {
325	                MEDIA_ERR("Failed to find subgraph filter %s\n", filter_name);
326	                ret = -EINVAL;
327	                goto out;
328	            }
329	
330	            if (!config_end)
331	                break;
332	            current = config_end + strlen(SUBGRAPH_PARSER_FLAGS);
333	        }
334	    }
335	
336	    priv->pollftn = 0;
337	    for (fd = 0; fd < priv->graph->nb_filters; fd++) {
338	        AVFilterContext* filter = priv->graph->filters[fd];
339	
340	        if ((filter->filter->flags & AVFILTER_FLAG_SUPPORT_POLL) != 0) {
341	            priv->pollfts[priv->pollftn++] = filter;
342	            if (priv->pollftn > MAX_POLL_FILTERS) {
343	                MEDIA_ERR("%s, media graph too many pollfds\n", __func__);
344	                ret = -EINVAL;
345	                goto out;
346	            }
347	        }
348	    }
349	
350	    MEDIA_INFO("%s, loadgraph succeed\n", __func__);
351	    return 0;
352	out:
353	    avfilter_graph_free(&priv->graph);
354	    return ret;
355	}
