444	static int audio_graph_queue_command(MediaGraphPriv* priv, AVFilterContext* filter,
445	    const char* cmd, const char* arg, char* res, int res_len, int flags)
446	{
447	    MediaCommand* newcmd = NULL;
448	    char msg[128];
449	    int ret = 0;
450	
451	    if (audio_graph_immediate_cmd(cmd)) {
452	        if (!strcmp(cmd, "volume")) {
453	            snprintf(msg, sizeof(msg), "volume=%.*s", (int)(sizeof(msg) - 8), arg ? arg : "");
454	            return avfilter_process_command(filter, "set_parameter", msg, res, res_len, 0);
455	        }
456	
457	        return avfilter_process_command(filter, cmd, arg, res, res_len, flags);
458	    }
459	
460	    newcmd = audio_graph_create_command(cmd, arg, res, filter);
461	    if (!newcmd)
462	        return -ENOMEM;
463	
464	    pthread_mutex_lock(&priv->qlock);
465	    TAILQ_INSERT_TAIL(&priv->cmdq, newcmd, entries);
466	    pthread_mutex_unlock(&priv->qlock);
467	
468	    audio_graph_try_touch(priv);
469	
470	    av_log(NULL, AV_LOG_INFO, "Pending command: %s %s\n", cmd, arg ? arg : "_");
471	    return ret;
472	}
