474	static int audio_graph_dequeue_command(MediaGraphPriv* priv, bool process)
475	{
476	    MediaCommand* cmd = NULL;
477	    int i, j, ret = 0;
478	
479	    pthread_mutex_lock(&priv->qlock);
480	    cmd = TAILQ_FIRST(&priv->cmdq);
481	    if (!cmd) {
482	        pthread_mutex_unlock(&priv->qlock);
483	        return -EAGAIN;
484	    }
485	
486	    if (!process) {
487	        TAILQ_REMOVE(&priv->cmdq, cmd, entries);
488	        pthread_mutex_unlock(&priv->qlock);
489	        goto exit;
490	    }
491	    pthread_mutex_unlock(&priv->qlock);
492	
493	    av_log(NULL, AV_LOG_INFO, "process %s %s %s\n",
494	        cmd->filter->name, cmd->cmd, cmd->arg ? cmd->arg : "_");
495	
496	    if (!strcmp(cmd->cmd, "link") || !strcmp(cmd->cmd, "map")) {
497	        for (i = 0; i < cmd->filter->nb_outputs; i++) {
498	            AVFilterLink* outlink = cmd->filter->outputs[i];
499	            FilterLinkInternal* li = (FilterLinkInternal*)outlink;
500	
501	            if (li->status_in != li->status_out) {
502	                MEDIA_WARN("%s outlink %d is not EOF synchronized, cmd '%s' pending\n",
503	                    cmd->filter->name, i, cmd->cmd);
504	                return -EAGAIN;
505	            }
506	
507	            if (outlink->dst && outlink->dst->nb_outputs > 0) {
508	                for (j = 0; j < outlink->dst->nb_outputs; j++) {
509	                    AVFilterLink* dst_outlink = outlink->dst->outputs[j];
510	                    FilterLinkInternal* dst_li = (FilterLinkInternal*)dst_outlink;
511	
512	                    if (dst_li->status_in != dst_li->status_out) {
513	                        MEDIA_WARN("%s (downstream of %s) outlink %d not EOF synchronized, cmd '%s' pending\n",
514	                            outlink->dst->name, cmd->filter->name, j, cmd->cmd);
515	                        return -EAGAIN;
516	                    }
517	                }
518	            }
519	        }
520	
521	        ret = avfilter_process_command(cmd->filter, cmd->cmd, cmd->arg, cmd->res, 0, 0);
522	        if (ret >= 0) {
523	            MEDIA_INFO("Processed %s %s on %s\n",
524	                cmd->cmd, cmd->arg ? cmd->arg : "_", cmd->filter->name);
525	            ret = audio_negotiation_trigger(cmd->filter);
526	            if (ret < 0)
527	                MEDIA_ERR("Media graph link error after command '%s': %d:%s\n",
528	                    cmd->cmd, ret, av_err2str(ret));
529	        }
530	    } else
531	        ret = avfilter_process_command(cmd->filter, cmd->cmd, cmd->arg,
532	            cmd->res, 0, 0);
533	
534	    if (ret >= 0)
535	        audio_graph_try_touch(priv);
536	
537	    pthread_mutex_lock(&priv->qlock);
538	    TAILQ_REMOVE(&priv->cmdq, cmd, entries);
539	    pthread_mutex_unlock(&priv->qlock);
540	
