563	static int audio_graph_get_pollfds(MediadPlugin* ctx, struct pollfd* fds,
564	    void** cookies, int count)
565	{
566	    MediaGraphPriv* priv = ctx->priv;
567	    int ret, nfd, i;
568	
569	    if (!fds || count < 2)
570	        return -EINVAL;
571	
572	    fds[0].fd = priv->fd;
573	    fds[0].events = POLLIN;
574	    cookies[0] = NULL;
575	    nfd = 1;
576	
577	    for (i = 0; i < priv->pollftn; i++) {
578	        AVFilterContext* filter = priv->pollfts[i];
579	
580	        ret = audio_graph_queue_command(priv, filter, "get_pollfd", NULL,
581	            (char*)&fds[nfd], sizeof(struct pollfd) * (count - nfd),
582	            AV_OPT_SEARCH_CHILDREN);
583	        if (ret < 0)
584	            continue;
585	
586	        while (ret--) {
587	            cookies[nfd++] = filter;
588	            if (nfd > count)
589	                return -EINVAL;
590	        }
591	    }
592	
593	    return nfd;
594	}
