619	static int audio_graph_run_all(AVFilterGraph* graph)
620	{
621	    FFFilterContext* ctxi;
622	    unsigned i;
623	    int ret;
624	
625	    while (1) {
626	        ctxi = fffilterctx(graph->filters[0]);
627	        for (i = 1; i < graph->nb_filters; i++) {
628	            FFFilterContext* ctxi_other = fffilterctx(graph->filters[i]);
629	            if (ctxi_other->ready > ctxi->ready)
630	                ctxi = ctxi_other;
631	        }
632	        if (!ctxi->ready) {
633	            ret = 0;
634	            break;
635	        }
636	
637	        ret = ff_filter_activate(&ctxi->p);
638	        if (ret < 0 && ret != AVERROR_EOF && ret != AVERROR(EAGAIN)) {
639	            av_log(graph, AV_LOG_ERROR, "%s %s activate failed, ret %d.\n", __func__, ctxi->p.name, ret);
640	            break;
641	        }
642	    }
643	
644	    return ret;
645	}
