647	static int audio_graph_run_once(MediadPlugin* ctx)
648	{
649	    MediaGraphPriv* priv = ctx->priv;
650	    int ret;
651	
652	    ret = audio_graph_run_all(priv->graph);
653	    if (ret < 0)
654	        return ret;
655	
656	    do {
657	        ret = audio_graph_dequeue_command(priv, true);
658	    } while (ret >= 0);
659	
660	    return ret == -EAGAIN ? 0 : ret;
661	}
