663	static int audio_graph_dump_link(AVBPrint* buf, AVFilterLink* link, const char* filter_ext_info)
664	{
665	    const char* format;
666	    AVBPrint dummy_buffer;
667	    FilterLinkInternal* li = ff_link_internal(link);
668	
669	    if (!buf) {
670	        buf = &dummy_buffer;
671	        av_bprint_init(buf, 0, AV_BPRINT_SIZE_COUNT_ONLY);
672	    }
673	    switch (link->type) {
674	    case AVMEDIA_TYPE_VIDEO:
675	        format = av_x_if_null(av_get_pix_fmt_name(link->format), "?");
676	        av_bprintf(buf, "[%dx%d %d:%d %s]", link->w, link->h,
677	            link->sample_aspect_ratio.num,
678	            link->sample_aspect_ratio.den,
679	            format);
680	        break;
681	
682	    case AVMEDIA_TYPE_AUDIO:
683	        format = av_x_if_null(av_get_sample_fmt_name(link->format), "?");
684	        av_bprintf(buf, "[%dHz %s: status_in:%d status_out: %d fifo:%d wt:%d icnt:%" PRId64 " ocnt:%" PRId64 " ",
685	            (int)link->sample_rate, format, li->status_in, li->status_out, (int)ff_framequeue_queued_frames(&li->fifo),
686	            li->frame_wanted_out, li->l.frame_count_in, li->l.frame_count_out);
687	        av_channel_layout_describe_bprint(&link->ch_layout, buf);
688	        if (filter_ext_info && filter_ext_info[0]) {
689	            av_bprintf(buf, " ext:%s", filter_ext_info);
690	        }
691	        av_bprint_chars(buf, ']', 1);
692	        break;
693	
694	    default:
695	        av_bprintf(buf, "?");
696	        break;
697	    }
698	    return buf->len;
699	}
