701	static void audio_graph_dump_to_buf(AVBPrint* buf, AVFilterGraph* graph)
702	{
703	    unsigned i, j, x, e;
704	
705	    if (!graph) {
706	        av_bprintf(buf, "<null graph>\n");
707	        return;
708	    }
709	
710	    for (i = 0; i < graph->nb_filters; i++) {
711	        AVFilterContext* filter = graph->filters[i];
712	        unsigned max_src_name = 0, max_dst_name = 0;
713	        unsigned max_in_name = 0, max_out_name = 0;
714	        unsigned max_in_fmt = 0, max_out_fmt = 0;
715	        unsigned width, height, in_indent;
716	        unsigned lname;
717	        unsigned ltype;
718	        char filter_ext_info[256] = { 0 };
719	        int ret;
720	
721	        if (!filter || !filter->name || !filter->filter ||
722	            !filter->filter->name) {
723	            av_bprintf(buf, "<invalid filter %u>\n", i);
724	            continue;
725	        }
726	
727	        lname = strlen(filter->name);
728	        ltype = strlen(filter->filter->name);
729	
730	        /* Send dump command to filter to get extra info */
731	        if (filter->filter->process_command) {
732	            ret = avfilter_process_command(filter, "dump", NULL, filter_ext_info, sizeof(filter_ext_info), 0);
733	            if (ret < 0) {
734	                filter_ext_info[0] = '\0';
735	            }
736	        }
737	
738	        for (j = 0; j < filter->nb_inputs; j++) {
739	            AVFilterLink* l = filter->inputs[j];
740	            unsigned ln;
741	
742	            if (!l || !l->src || !l->src->name || !l->srcpad ||
743	                !l->srcpad->name || !l->dstpad || !l->dstpad->name)
744	                continue;
745	
746	            ln = strlen(l->src->name) + 1 + strlen(l->srcpad->name);
747	            max_src_name = FFMAX(max_src_name, ln);
748	            max_in_name = FFMAX(max_in_name, strlen(l->dstpad->name));
749	            max_in_fmt = FFMAX(max_in_fmt, audio_graph_dump_link(NULL, l, filter_ext_info));
750	        }
751	        for (j = 0; j < filter->nb_outputs; j++) {
752	            AVFilterLink* l = filter->outputs[j];
753	            unsigned ln;
754	
755	            if (!l || !l->dst || !l->dst->name || !l->dstpad ||
756	                !l->dstpad->name || !l->srcpad || !l->srcpad->name)
757	                continue;
758	
759	            ln = strlen(l->dst->name) + 1 + strlen(l->dstpad->name);
760	            max_dst_name = FFMAX(max_dst_name, ln);
761	            max_out_name = FFMAX(max_out_name, strlen(l->srcpad->name));
762	            max_out_fmt = FFMAX(max_out_fmt, audio_graph_dump_link(NULL, l, filter_ext_info));
763	        }
764	        in_indent = max_src_name + max_in_name + max_in_fmt;
765	        in_indent += in_indent ? 4 : 0;
766	        width = FFMAX(lname + 2, ltype + 4);
767	        height = FFMAX3(2, filter->nb_inputs, filter->nb_outputs);
768	        av_bprint_chars(buf, ' ', in_indent);
769	        av_bprintf(buf, "+");
770	        av_bprint_chars(buf, '-', width);
771	        av_bprintf(buf, "+\n");
772	        for (j = 0; j < height; j++) {
773	            unsigned in_no = j - (height - filter->nb_inputs) / 2;
774	            unsigned out_no = j - (height - filter->nb_outputs) / 2;
775	
776	            /* Input link */
777	            if (in_no < filter->nb_inputs) {
778	                AVFilterLink* l = filter->inputs[in_no];
779	                if (l && l->src && l->src->name && l->srcpad &&
780	                    l->srcpad->name && l->dstpad && l->dstpad->name) {
781	                    e = buf->len + max_src_name + 2;
782	                    av_bprintf(buf, "%s:%s", l->src->name, l->srcpad->name);
783	                    av_bprint_chars(buf, '-', e - buf->len);
784	                    e = buf->len + max_in_fmt + 2 + max_in_name - strlen(l->dstpad->name);
785	                    audio_graph_dump_link(buf, l, filter_ext_info);
786	                    av_bprint_chars(buf, '-', e - buf->len);
787	                    av_bprintf(buf, "%s", l->dstpad->name);
788	                } else {
789	                    av_bprintf(buf, "<invalid input>");
790	                }
791	            } else {
792	                av_bprint_chars(buf, ' ', in_indent);
793	            }
794	
795	            /* Filter */
796	            av_bprintf(buf, "|");
797	            if (j == (height - 2) / 2) {
798	                x = (width - lname) / 2;
799	                av_bprintf(buf, "%*s%-*s", x, "", width - x, filter->name);
800	            } else if (j == (height - 2) / 2 + 1) {
801	                x = (width - ltype - 2) / 2;
802	                av_bprintf(buf, "%*s(%s)%*s", x, "", filter->filter->name,
803	                    width - ltype - 2 - x, "");
804	            } else {
805	                av_bprint_chars(buf, ' ', width);
806	            }
807	            av_bprintf(buf, "|");
808	
809	            /* Output link */
810	            if (out_no < filter->nb_outputs) {
811	                AVFilterLink* l = filter->outputs[out_no];
812	                if (l && l->dst && l->dst->name && l->dstpad &&
813	                    l->dstpad->name && l->srcpad && l->srcpad->name) {
814	                    unsigned ln = strlen(l->dst->name) + 1 + strlen(l->dstpad->name);
815	                    e = buf->len + max_out_name + 2;
816	                    av_bprintf(buf, "%s", l->srcpad->name);
817	                    av_bprint_chars(buf, '-', e - buf->len);
818	                    e = buf->len + max_out_fmt + 2 + max_dst_name - ln;
819	                    audio_graph_dump_link(buf, l, filter_ext_info);
820	                    av_bprint_chars(buf, '-', e - buf->len);
821	                    av_bprintf(buf, "%s:%s", l->dst->name, l->dstpad->name);
822	                } else {
823	                    av_bprintf(buf, "<invalid output>");
824	                }
825	            }
826	            av_bprintf(buf, "\n");
827	        }
828	        av_bprint_chars(buf, ' ', in_indent);
829	        av_bprintf(buf, "+");
830	        av_bprint_chars(buf, '-', width);
831	        av_bprintf(buf, "+\n");
832	        av_bprintf(buf, "\n");
833	    }
834	}
