851	static int audio_graph_handler(MediadPlugin* ctx, struct media_server_conn* conn, const char* target, const char* cmd,
852	    const char* arg, int flags, char* res, int res_len)
853	{
854	    MediaGraphPriv* priv = ctx->priv;
855	    int i, ret = 0;
856	    char* dump;
857	
858	    MEDIA_INFO("cookie %p target %s cmd %s arg %s flags %d res %p res_len %d\n",
859	        conn, target, cmd, arg, flags, res, res_len);
860	
861	    if (!target && !strcmp(cmd, "dump")) {
862	        dump = audio_graph_server_dump(priv->graph, NULL);
863	        if (dump)
864	            MEDIA_INFO("\n%s\n", dump);
865	
866	        av_free(dump);
867	        return 0;
868	    } else if (!strcmp(cmd, "loglevel")) {
869	        if (!arg)
870	            return -EINVAL;
871	
872	        av_log_set_level(strtol(arg, NULL, 0));
873	        return 0;
874	    }
875	
876	    if (!target)
877	        return -EINVAL;
878	
879	    for (i = 0; i < priv->graph->nb_filters; i++) {
880	        AVFilterContext* filter = priv->graph->filters[i];
881	
882	        if (!strcmp(target, filter->name)) {
883	            ret = audio_graph_queue_command(priv, filter, cmd, arg, res, res_len, flags);
884	        } else {
885	            const char* tmp = strchr(filter->name, '@');
886	
887	            if (tmp && !strncmp(tmp + 1, target, strlen(target)))
888	                ret = audio_graph_queue_command(priv, filter, cmd, arg, res, res_len, flags);
889	        }
890	
891	        if (ret < 0)
892	            return ret;
893	    }
894	
895	    return 0;
896	}
