840	    }
841	
842	    ctx->state = MEDIA_RECORDER_STATE_STOPPED;
843	    ctx->audio_idx = -1;
844	    ctx->video_idx = -1;
845	    ctx->exit = 0;
846	    ctx->aframe_cnt = 0;
847	    ctx->audio_input_state = 0;
848	    SIMPLEQ_INIT(&ctx->cmd_queue);
849	    media_parcel_init(&ctx->parcel);
850	    pthread_mutex_init(&ctx->mutex, NULL);
851	    ctx->event_fd = eventfd(0, EFD_NONBLOCK | EFD_CLOEXEC);
852	}
