854	static void media_recorder_ctx_release(MediaRecorderContext* ctx)
855	{
856	    ctx->state = MEDIA_RECORDER_STATE_IDLE;
857	    ctx->audio_idx = -1;
858	    ctx->video_idx = -1;
859	    ctx->nb_streams = 0;
860	    ctx->event = 0;
861	    media_recorder_notify_finalize(ctx);
862	    media_parcel_deinit(&ctx->parcel);
863	    pthread_mutex_destroy(&ctx->mutex);
864	    close(ctx->event_fd);
865	    ctx->event_fd = -1;
866	}
867	
868	static int media_recorder_pause(MediaRecorderContext* ctx)
869	{
870	    int ret = 0;
871	
872	    if (ctx->state != MEDIA_RECORDER_STATE_STARTED) {
873	        ret = AVERROR(EPERM);
874	        goto out;
875	    }
876	
877	    if (ctx->audio_idx >= 0) {
878	        ret = audio_graph_pause(ctx->audio_input);
879	        if (ret < 0)
880	            goto out;
881	    }
882	
883	    ctx->state = MEDIA_RECORDER_STATE_PAUSED;
884	
885	out:
886	    media_recorder_event_cb(ctx, MEDIA_EVENT_PAUSED, ret, NULL);
887	    return ret;
888	}
889	
890	static int media_recorder_stop(MediaRecorderContext* ctx)
891	{
892	    int ret;
893	    if (ctx->state == MEDIA_RECORDER_STATE_STOPPED)
894	        return 0;
895	
896	    if (ctx->audio_idx >= 0)
897	        audio_graph_stop(ctx->audio_input);
898	
899	    if (ctx->state == MEDIA_RECORDER_STATE_PREPARED || ctx->state == MEDIA_RECORDER_STATE_COMPLETED)
900	        goto out;
901	
902	    // send empty frame to flush encoder
903	    ret = media_recorder_send_empty_frame(ctx);
904	    while (!ret) {
905	        ret = media_recorder_proc_dat(ctx);
906	    }
907	
908	out:
909	    media_recorder_clean(ctx);
910	    return 0;
911	}
912	
913	static int media_recorder_start(MediaRecorderContext* ctx)
914	{
915	    int ret = AVERROR(EPERM);
916	    int i;
917	
918	    if (ctx->state != MEDIA_RECORDER_STATE_PREPARED && ctx->state != MEDIA_RECORDER_STATE_PAUSED)
919	        goto out;
920	
921	    if (ctx->state == MEDIA_RECORDER_STATE_PREPARED) {
922	        for (i = 0; i < ctx->nb_streams; i++) {
923	            ret = media_recorder_open_encoder(ctx, i);
924	            if (ret < 0)
925	                goto out;
926	        }
927	
928	        ret = avformat_write_header(ctx->format_ctx, NULL);
929	        if (ret < 0)
930	            goto out;
931	    }
932	
933	    if (ctx->audio_idx >= 0) {
934	        if (ctx->streams[ctx->audio_idx].enc_ctx->frame_size) {
935	            char buf[16] = { 0 };
936	            snprintf(buf, sizeof(buf), "%d", ctx->streams[ctx->audio_idx].enc_ctx->frame_size);
937	            ret = audio_graph_set_parameter(ctx->audio_input, "frame_size", buf);
938	            if (ret < 0) {
939	                MEDIA_ERR("ctx %p audio_graph_set_parameter failed.\n", ctx);
940	                goto out;
941	            }
942	        }
943	        if (ctx->state == MEDIA_RECORDER_STATE_PAUSED) {
944	            ret = audio_graph_resume(ctx->audio_input);
945	            if (ret < 0) {
946	                MEDIA_ERR("ctx %p audio_graph_resume failed, ret %d.\n", ctx, ret);
947	                goto out;
948	            } else
949	                MEDIA_INFO("ctx %p audio_graph_resume success.\n", ctx);
950	        } else {
951	            ret = audio_graph_start(ctx->audio_input,
952	                ctx->streams[ctx->audio_idx].enc_ctx->sample_fmt,
953	                ctx->streams[ctx->audio_idx].enc_ctx->sample_rate,
954	                ctx->streams[ctx->audio_idx].enc_ctx->ch_layout.nb_channels,
955	                media_recorder_on_event_cb, ctx);
956	            if (ret < 0) {
957	                MEDIA_ERR("ctx %p audio_graph_start failed, ret %d.\n", ctx, ret);
958	                goto out;
959	            } else
960	                MEDIA_INFO("ctx %p audio_graph_start success.\n", ctx);
961	        }
962	        ctx->audio_input_state = 1;
963	    }
964	
965	    ctx->state = MEDIA_RECORDER_STATE_STARTED;
966	
967	out:
968	    media_recorder_event_cb(ctx, MEDIA_EVENT_STARTED, ret, NULL);
969	    return ret;
970	}
971	
972	static void media_recorder_close(MediaRecorderContext* ctx)
973	{
974	    media_recorder_release_stream(ctx);
975	
976	    if (ctx->audio_input)
977	        audio_graph_close(&ctx->audio_input);
978	
979	    if (ctx->tran_fd > 0)
980	        media_recorder_conn_close(ctx);
981	}
982	
983	static int media_recorder_prepare(MediaRecorderContext* ctx, const char* filename)
984	{
985	    int ret = AVERROR(EPERM);
986	    AVDictionaryEntry* tag;
987	    char* format = NULL;
988	
989	    if (ctx->state != MEDIA_RECORDER_STATE_STOPPED)
990	        goto out;
991	
992	    if ((tag = av_dict_get(ctx->format_opt, "format", NULL, 0)))
993	        format = tag->value;
994	
995	    ctx->format = av_guess_format(format, filename, NULL);
996	    if (!ctx->format) {
997	        MEDIA_ERR("ctx %p unknown format.\n", ctx);
998	        ret = AVERROR(EINVAL);
999	        goto out;

    MEDIA_INFO("ctx %p %s recorder thread exit.\n", ctx, ctx->name);
    return NULL;
}

static int media_recorder_open(MediaRecorderContext* ctx, const char* name)
{
    struct sched_param param;
    pthread_attr_t attr;
    pthread_t thread;
    int ret = -EINVAL;

    if (ctx->state != MEDIA_RECORDER_STATE_IDLE || name == NULL)
        return ret;

    media_recorder_ctx_init(ctx);

    audio_graph_open(&ctx->audio_input, name);
    if (ctx->audio_input == NULL) {
        MEDIA_ERR("ctx %p open audio input failed\n", ctx);
        goto out;
    }

    pthread_attr_init(&attr);
    pthread_attr_setstacksize(&attr, CONFIG_MEDIA_RECORDER_STACKSIZE);
    param.sched_priority = CONFIG_MEDIA_RECORDER_PRIORITY;
    pthread_attr_setschedparam(&attr, &param);
    ret = pthread_create(&thread, &attr, media_recorder_thread, ctx);
    pthread_attr_destroy(&attr);
    if (ret != 0) {
        MEDIA_ERR("ctx %p create recorder thread failed %d\n", ctx, ret);
        goto out;
    }

    pthread_setname_np(thread, ctx->name);
    pthread_detach(thread);

    return 0;

out:
    audio_graph_close(&ctx->audio_input);
    ctx->state = MEDIA_RECORDER_STATE_IDLE;
    return ret;
}

