38	#define INPUT_ON       1    /**< input is active */
39	#define INPUT_EOF      2    /**< input has reached EOF (may still be active) */
40	
41	#define SINK_STATE_IDLE    0    /**< sink is idle (not linked) */
42	#define SINK_STATE_RUNNING 1    /**< sink is running (linked and active) */
43	#define SINK_STATE_PAUSED  2    /**< sink is paused (linked but inactive) */
44	
45	typedef struct ABufSinkPriv {
46	    const AVClass *class;
47	
48	    int nb_inputs;                  /**< number of inputs */
49	
50	    int64_t next_pts;               /**< calculated pts for next output frame */
51	
52	    int sample_rate;                /**< sample rate */
53	    AVChannelLayout ch_layout;      /**< channel layout */
54	    enum AVSampleFormat sample_fmt; /**< sample format */
55	
56	    int state;                      /**< sink state: IDLE/RUNNING/PAUSED */
57	
58	    AMixContext *mix;               /**< mix module context */
59	    int frame_size;                 /**< frame size */
60	
61	    int (*on_event_cb)(void *udata, int evt, int64_t args);
62	    void *on_event_cb_udata;
63	} ABufSinkPriv;
64	
65	#define OFFSET(x) offsetof(ABufSinkPriv, x)
66	#define A AV_OPT_FLAG_AUDIO_PARAM
67	#define F AV_OPT_FLAG_FILTERING_PARAM
68	static const AVOption abufsink_options[] = {
69	    { "inputs", "Number of inputs.",
70	            OFFSET(nb_inputs), AV_OPT_TYPE_INT, {.i64 = 1}, 1, INT16_MAX, A|F },
71	    { "state", "Sink state (0=IDLE, 1=RUNNING, 2=PAUSED).",
72	            OFFSET(state), AV_OPT_TYPE_INT, {.i64 = SINK_STATE_IDLE}, SINK_STATE_IDLE, SINK_STATE_PAUSED, A|F },
73	    { NULL }
