78	static void av_abufsink_set_event_cb(AVFilterContext *ctx,
79	    int (*on_event_cb)(void *udata, int evt, int64_t args), void *udata)
80	{
81	    ABufSinkPriv *s = ctx->priv;
82	
83	    s->on_event_cb = on_event_cb;
84	    s->on_event_cb_udata = udata;
85	
86	    ff_filter_set_ready(ctx, 100);
87	}
88	
89	static void request_frame(AVFilterContext *ctx)
90	{
91	    ABufSinkPriv *s = ctx->priv;
92	    bool activate = true;
93	    AVFilterLink *link;
94	    int ret, pad, count = 0;
95	    int64_t pts;
96	
97	    for (pad = 0; pad < ctx->nb_inputs; pad++) {
98	        link = ctx->inputs[pad];
99	
100	        ff_inlink_acknowledge_status(link, &ret, &pts);
101	        if (ret < 0){
102	            /* In case that all inputs are in EOF, but there is data remains in link. */
103	            if (ff_amix_input_empty(s->mix, link))
104	                count++;
105	            continue;
106	        }
107	
108	        if (!s->mix || ff_amix_input_want(s->mix, link)) {
109	            ff_inlink_request_frame(link);
110	            activate = false;
111	        }
112	    }
113	
114	    if (activate && count < ctx->nb_inputs)
115	        ff_filter_set_ready(ctx, 100);
116	}
117	
118	static int output_frame(AVFilterContext *ctx)
119	{
120	    ABufSinkPriv *s = ctx->priv;
121	    AVFrame *frame = NULL;
122	    int ret;
123	
124	    if (!s->mix)
125	        return AVERROR(EINVAL);
126	
127	    ret = ff_amix_read(s->mix, &frame);
128	    if (ret <= 0)
129	        return ret;
130	
131	    if (s->on_event_cb && s->state == SINK_STATE_RUNNING) {
132	        if (s->next_pts == AV_NOPTS_VALUE)
133	            s->next_pts = 0;
134	
135	        frame->pts = s->next_pts;
136	        frame->duration = av_rescale_q(frame->nb_samples, av_make_q(1, frame->sample_rate), AV_TIME_BASE_Q);
137	        s->next_pts += frame->duration;
138	
139	        s->on_event_cb(s->on_event_cb_udata, 0, (intptr_t)frame);
140	    }
141	
142	    av_frame_free(&frame);
143	
144	    return 0;
145	}
146	
147	static int abufsink_activate(AVFilterContext *ctx)
148	{
149	    ABufSinkPriv *s = ctx->priv;
150	    AVFilterLink *link;
151	    int i, ret = 0;
152	    int64_t pts;
153	
154	    for (i = 0; i < s->nb_inputs; i++) {
155	        link = ctx->inputs[i];
156	
157	        if (ff_inlink_check_available_frame(link)) {
158	            if (!s->mix && s->on_event_cb) {
159	                s->mix = ff_amix_alloc(s->sample_rate, s->sample_fmt, s->ch_layout.nb_channels);
160	                if (!s->mix)
161	                    return AVERROR(ENOMEM);
162	                if (s->frame_size)
163	                    ff_amix_set_frame_size(s->mix, s->frame_size);
164	            }
165	
166	            ret = ff_amix_input_write(s->mix, link);
167	            if (ret < 0) {
168	                av_log(ctx, AV_LOG_ERROR, "input[%d] write to mix failed, ret:%d.\n", i, ret);
169	                continue;
170	            }
171	        }
172	    }
173	
174	    output_frame(ctx);
175	
176	    if (s->on_event_cb)
177	        request_frame(ctx);
178	    else {
179	        for (i = 0; i < s->nb_inputs; i++) {
180	            link = ctx->inputs[i];
181	            ff_inlink_set_status(link, AVERROR_EOF);
182	            if (!ff_amix_input_empty(s->mix, ctx->inputs[i])) {
183	                ff_filter_set_ready(ctx, 100);
184	                break;
185	            }
186	        }
187	
188	        if (i == s->nb_inputs) {
189	            ff_amix_free(s->mix);
190	            s->mix = NULL;
191	        }
192	    }
193	
194	    return 0;
195	}
