197	static int abufsink_set_parameter(AVFilterContext *ctx, const char *args)
198	{
199	    ABufSinkPriv *s = ctx->priv;
200	    char *key = NULL, *value = NULL;
201	    const char *p = args;
202	    int ret = 0;
203	
204	    av_log(ctx, AV_LOG_INFO, "Parsing args: %s\n", args);
205	
206	    while (*p) {
207	        ret = av_opt_get_key_value(&p, "=", ":", 0, &key, &value);
208	        if (ret < 0) {
209	            av_log(ctx, AV_LOG_ERROR, "Unable to parse '%s': %s\n", p, av_err2str(ret));
210	            break;
211	        }
212	        if (*p)
213	            p++;
214	        av_log(ctx, AV_LOG_INFO, "Parsed Key: %s, Value: %s\n", key, value);
215	        if (!strcmp(key, "frame_size"))
216	            s->frame_size = strtol(value, NULL, 0);
217	        else
218	            av_log(ctx, AV_LOG_ERROR, "Unknown parameter: %s\n", key);
219	
220	        av_freep(&key);
221	        av_freep(&value);
222	    }
223	    return ret;
224	}
