226	static int abufsink_process_command(AVFilterContext *ctx, const char *cmd, const char *args,
227	                                  char *res, int res_len, int flags)
228	{
229	    ABufSinkPriv *sink = ctx->priv;
230	    int ret;
231	
232	    if (!strcmp(cmd, "link")) {
233	        int (*on_event_cb)(void *udata, int evt, int64_t args);
234	        int format, sample_rate, channels;
235	        void *udata;
236	
237	        if (!args)
238	            return AVERROR(EINVAL);
239	
240	        if (sscanf(args, "%p %p fmt=%d:rate=%d:ch=%d", &on_event_cb, &udata, &format, &sample_rate, &channels) != 5)
241	            return AVERROR(EINVAL);
242	
243	        sink->sample_fmt = format;
244	        sink->sample_rate = sample_rate;
245	        av_channel_layout_default(&sink->ch_layout, channels);
246	
247	        if (!sink->on_event_cb)
248	            av_abufsink_set_event_cb(ctx, on_event_cb, udata);
249	        sink->state = SINK_STATE_RUNNING;
250	        return 0;
251	    } else if (!strcmp(cmd, "unlink")) {
252	        if (sink->on_event_cb)
253	            sink->on_event_cb(sink->on_event_cb_udata, -1, 0);
254	
255	        sink->frame_size = 0;
256	        sink->next_pts = AV_NOPTS_VALUE;
257	        sink->sample_fmt = AV_SAMPLE_FMT_NONE;
258	        sink->sample_rate = 0;
259	        av_channel_layout_uninit(&sink->ch_layout);
260	        av_abufsink_set_event_cb(ctx, NULL, NULL);
261	        sink->state = SINK_STATE_IDLE;
262	        return 0;
263	    } else if (!strcmp(cmd, "set_parameter")) {
264	        if (!args)
265	            return AVERROR(EINVAL);
266	
267	        return abufsink_set_parameter(ctx, args);
268	    } else if (!av_strcasecmp(cmd, "pause")) {
269	        sink->state = SINK_STATE_PAUSED;
270	        return 0;
271	    } else if (!av_strcasecmp(cmd, "resume")) {
272	        sink->state = SINK_STATE_RUNNING;
273	        ff_filter_set_ready(ctx, 100);
274	        return 0;
275	    }
276	
277	    return ff_filter_process_command(ctx, cmd, args, res, res_len, flags);
278	}
279	
280	static int abufsink_init(AVFilterContext *ctx)
281	{
282	    ABufSinkPriv *s = ctx->priv;
283	    int i, ret;
284	
285	    for (i = 0; i < s->nb_inputs; i++) {
286	        AVFilterPad pad = { 0 };
287	
288	        pad.type = AVMEDIA_TYPE_AUDIO;
289	        pad.name = av_asprintf("input%d", i);
290	        if (!pad.name)
291	            return AVERROR(ENOMEM);
292	
293	        if ((ret = ff_append_inpad_free_name(ctx, &pad)) < 0)
294	            return ret;
295	    }
296	
297	    s->next_pts = AV_NOPTS_VALUE;
298	    s->state = SINK_STATE_IDLE;
299	
300	    return 0;
301	}
302	
303	static int abufsink_query_formats(const AVFilterContext *ctx, AVFilterFormatsConfig **cfg_in,
304	                               AVFilterFormatsConfig **cfg_out)
305	{
306	    AVFilterFormats *formats = NULL;
307	    ABufSinkPriv *sink = ctx->priv;
308	    int ret = AVERROR(EINVAL), i;
309	
310	    for (i = 0; i < ctx->nb_inputs; i++) {
311	        int list[] = { 0, -1 };
312	
313	        list[0] = sink->sample_fmt;
314	        formats = ff_make_format_list(list);
315	        if (!formats)
316	            goto out;
317	
318	        ff_formats_unref(&cfg_in[i]->formats);
319	        ret = ff_formats_ref(formats, &cfg_in[i]->formats);
320	        if (ret < 0)
321	            goto out;
322	
323	        /* Do not constrain sample_rate / channel_layout on the link: the
324	         * internal amix resamples any input to the recorder-requested target
325	         * (set via the "link" command). Advertising the amix target here would
326	         * force the upstream link format and make pass-through filters (e.g.
327	         * volume) deliver frames that fail ff_filter_frame's consistency check.
328	         * Leaving these NULL means "accept any", so the link inherits the
329	         * source format and frames flow; amix then converts internally.
330	         */
331	        ret = 0;
332	    }
333	
334	out:
335	    return ret;
336	}
