717	int ff_nuttx_poll_available(NuttxPriv *priv, bool nonblock)
718	{
719	    struct audio_buf_desc_s buf_desc;
720	    int new, old = dq_count(&priv->bufferq);
721	
722	    while (1) {
723	        struct ap_buffer_s *buffer;
724	        struct audio_msg_s msg;
725	        struct mq_attr stat;
726	        int ret;
727	
728	        ret = mq_getattr(priv->mq, &stat);
729	        if (ret < 0)
730	            return AVERROR(errno);
731	
732	        if (nonblock && !stat.mq_curmsgs)
733	            break;
734	
735	        ret = mq_receive(priv->mq, (char *)&msg, sizeof(msg), NULL);
736	        if (ret < 0)
737	            return AVERROR(errno);
738	
739	        if (msg.msg_id == AUDIO_MSG_DEQUEUE) {
740	            if (!priv->running && priv->draining) {
741	                buf_desc.u.buffer = msg.u.ptr;
742	                ff_nuttx_ioctl(priv->fd, AUDIOIOC_FREEBUFFER, &buf_desc);
743	            } else {
744	                buffer = msg.u.ptr;
745	                buffer->curbyte = 0;
746	                dq_addlast(&buffer->dq_entry, &priv->bufferq);
747	            }
748	        } else if (msg.msg_id == AUDIO_MSG_COMPLETE) {
749	            av_log(priv, AV_LOG_INFO, "[%s][%s] complete\n", __func__, priv->devname);
750	            priv->draining = false;
751	            if (priv->mq >= 0)
752	                ff_nuttx_ioctl(priv->fd, AUDIOIOC_UNREGISTERMQ, 0);
753	            if (!priv->running)
754	                ff_nuttx_ioctl(priv->fd, AUDIOIOC_RELEASE, NULL);
755	            else
756	                return AVERROR_EXIT;
757	        } else if (msg.msg_id == AUDIO_MSG_UNDERRUN) {
758	            av_log(priv, AV_LOG_WARNING, "[%s][%s] underflow! pause.\n", __func__, priv->devname);
759	            ff_nuttx_ioctl(priv->fd, AUDIOIOC_PAUSE, 0);
760	            priv->paused = true;
761	        } else if (msg.msg_id == AUDIO_MSG_IOERR) {
762	            av_log(priv, AV_LOG_ERROR, "[%s][%s]io error occur\n", __func__, priv->devname);
763	            priv->ioerr = true;
764	        }
765	
766	        nonblock = true;
767	    }
768	
769	    new = dq_count(&priv->bufferq);
770	    if (priv->periods > 1 && new == priv->periods && new > old && !priv->paused && priv->running) {
771	        if (priv->playback) {
772	            /* Try to send the buffer containing the remaining data to the driver */
773	            ff_nuttx_drain_buffer(priv, false);
774	            old = new;
775	            new = dq_count(&priv->bufferq);
776	            if (new >= old) {
777	                /* No buffer is sent to the driver,execute pause */
778	                av_log(priv, AV_LOG_WARNING, "[%s][%s] playback underflow! pause.\n",
779	                       __func__, priv->devname);
780	                ff_nuttx_ioctl(priv->fd, AUDIOIOC_PAUSE, 0);
781	                priv->paused = true;
782	            } else {
783	                /* A buffer is sent to the driver,pause will be done next time */
784	                av_log(priv, AV_LOG_INFO, "[%s][%s] enqueue remaining data\n",
785	                       __func__, priv->devname);
786	            }
787	        } else {
788	            av_log(priv, AV_LOG_WARNING, "[%s][%s] capture overflow!\n",
789	                   __func__, priv->devname);
790	            while (!dq_empty(&priv->bufferq)) {
791	                buf_desc.u.buffer = (struct ap_buffer_s *)dq_remfirst(&priv->bufferq);
792	                ff_nuttx_ioctl(priv->fd, AUDIOIOC_ENQUEUEBUFFER, &buf_desc);
793	            }
794	        }
795	    }
796	
797	    return new;
798	}
